import{_ as i,l as r,o,c as l,v as a,p as n,x as t,d as p,i as d,S as s}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"completion","description":"","frontmatter":{"title":"completion","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/completion.md","filePath":"cs/completion.md","lastUpdated":1789023840000}'),m={name:"cs/completion.md"};function _(h,e,f,u,E,A){const c=r("Mermaid");return o(),l("div",null,[e[1]||(e[1]=a('<h1 id="completion" tabindex="-1">completion <a class="header-anchor" href="#completion" aria-label="Permalink to &quot;completion&quot;">​</a></h1><div class="epigraph"><p>完成量表示「这件事已经发生过」：等待者睡到一次性事件，唤醒后事件仍然为真，不必再在循环里猜谓词。</p><footer>—— 据 Love, Linux Kernel Development；Hoare 管程里一次性会合的对照整理</footer></div><p><a href="/cs/monitor-condvar">上一课</a>用条件变量等任意谓词，Mesa 语义下必须循环检查。<a href="/cs/semaphore">信号量</a> 的 V 可以累计。缺口是内核里极常见的会合：<strong>completion</strong>——生产者做完初始化或 I/O，消费者 <code>wait_for_completion</code>，事件是一次性（或可再 init）的粘性真。本课钉这个窄对象，不把 RCU 请进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>wait(&amp;c)</code> 在管程里等的是「缓冲非空」这类会再变假的谓词。模块加载结束、设备探测结束、一次 DMA 做完，则「完成」一旦为真就保持，直到有人显式再清。用 condvar 也能写，但容易漏 <code>signal</code>、容易虚假唤醒后条件仍假。completion：内部计数或标志 + 等待队列，<code>complete</code> 后后来的 wait 立即通过。缺口不是再讲 Mesa 循环，而是这种<strong>粘性事件</strong>。</p><p><span class="marginnote"><code>complete_all</code> 唤醒当前所有等待者并把完成态留下；之后再 wait 的人也直接过。再武装需要 <code>reinit_completion</code>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>声明 <code>struct completion</code>。消费者 <code>wait_for_completion</code>：若已完成则返回，否则睡。生产者 <code>complete</code>：置完成，唤醒。可中断版本对接<a href="/cs/restart-syscall">重启系统调用</a> 与信号。超时版本失败则调用方处理；事件仍可能稍后到来，须规定是否还 complete。</p>',8)),(o(),n(s,null,{default:t(()=>[d(c,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22wait_for_completion%22%5D%20--%3E%20S%5B%22%E6%9C%AA%E5%AE%8C%E6%88%90%E5%88%99%E7%9D%A1%E7%9C%A0%22%5D%0A%20%20C%5B%22complete%22%5D%20--%3E%20DONE%5B%22%E7%B2%98%E6%80%A7%E5%AE%8C%E6%88%90%E6%80%81%22%5D%0A%20%20DONE%20--%3E%20W%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>与 IRQ：<a href="/cs/interrupt-bottom-half">中断下半部</a> 里可以 <code>complete</code>，等待者必须是线程上下文。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>completion 把「一次性会合」从通用管程里拆出来，减少谓词错误。它不是锁：完成不保护数据结构的互斥，只同步「可以开始用」。若完成前数据要可见，生产者在 <code>complete</code> 前要有 release 语义，消费者 wait 返回后 acquire——<a href="/cs/memory-barrier-os">内存屏障</a> 已给出。</p><p>多次 <code>complete</code> 对只 wait 一次的人通常只多算一次；语义以所用内核文档为准，主干只要求一次性事件不要靠「多 V 几次」来凑。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有 <code>wait_for_completion_*</code> 变体当手册。屏障、RCU 同步不是 completion：RCU 等的是「所有读者离开」，下一课。也不把 pthread_barrier 的 N 人会合写成同一对象。</p><p>后课默认：一次性事件用 completion。读多写少、读者不能睡也不能重试撕数据时，下一课 RCU 读者。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>completion：粘性「已发生」；wait 在线程，complete 可在下半部。</li><li>不替代互斥，只做会合。</li><li>无锁只读遍历是 RCU 课。</li><li>出处：Love, <em>LKD</em>。</li></ul>',9))])}const T=i(m,[["render",_]]);export{C as __pageData,T as default};
